const r = $input.first().json;
const plata = (n) => '$ ' + Number(n).toLocaleString('es-AR', {minimumFractionDigits: 2});
const lineas = ['*Cafeto · cierre del ' + r.fecha + '*', '',
  'Vendido: ' + plata(r.ventas_hoy), 'Ganancia bruta: ' + plata(r.ganancia_bruta_hoy)];
for (const m of (r.desglose_medios_pago_hoy || [])) lineas.push('  · ' + m.medio + ': ' + plata(m.total));
if (r.renglones_sin_costo_hoy) lineas.push('', 'Ojo: ' + r.renglones_sin_costo_hoy + ' renglón(es) vendidos sin costo cargado.');
const avisos = r.avisos || [];
if (avisos.length) { lineas.push('', '*Avisos*'); for (const a of avisos) lineas.push('  · ' + a.texto); }
return [{ json: { texto: lineas.join('\n') } }];

const r = $input.first().json;
const plata = (n) => '$ ' + Number(n).toLocaleString('es-AR', {minimumFractionDigits: 2});
const cc = r.cuentas_corrientes || {atrasados: [], vencen_pronto: []};
const vencimientos = r.vencimientos_proximos || [];
if (!vencimientos.length && !cc.atrasados.length && !cc.vencen_pronto.length) return [];
const lineas = ['*Cafeto · buen día*'];
if (vencimientos.length) {
  lineas.push('', '*Para pagar en estos días*');
  for (const v of vencimientos)
    lineas.push((v.vencido ? 'VENCIDO ' : '') + v.vence + ' · ' + v.a_quien + ' · ' + v.concepto + ' · ' + plata(v.monto));
}
if (cc.atrasados.length) {
  lineas.push('', '*Fiados atrasados* (te deben ' + plata(cc.te_deben) + ' en total)');
  for (const c of cc.atrasados)
    lineas.push('  · ' + c.cliente + ': ' + plata(c.vencido) + ' vencido' + (c.dias_de_atraso ? ', ' + c.dias_de_atraso + ' día(s)' : '') + (c.suspendido ? ' (suspendido)' : '') + (c.nota ? ' — ' + c.nota : ''));
}
if (cc.vencen_pronto.length) {
  lineas.push('', '*Fiados que vencen en estos días*');
  for (const c of cc.vencen_pronto) lineas.push('  · ' + c.vence + ' · ' + c.cliente + ' · ' + plata(c.falta));
}
return [{ json: { texto: lineas.join('\n') } }];

const p = $('Uno por producto').item.json;
const d = $input.item.json;
if (d.status !== 1 || !d.product) return null;
const cuerpo = {};
if (p.sin_foto && d.product.image_front_url) cuerpo.url = d.product.image_front_url.replace(/^http:/, 'https:');
const marca = (d.product.brands || '').split(',')[0].trim();
if (marca) cuerpo.marca = marca;
if (!cuerpo.url && !cuerpo.marca) return null;
return { json: { id: p.id, cuerpo } };

const r = $input.first().json;
if (!r.en_bandeja) {
  return [{ json: { ok: false, detail: r.detail || 'Cafeto no pudo pre-cargar la compra.', texto: 'Llegó una factura pero no se pudo pre-cargar la compra (' + (r.detail || 'sin detalle') + '). Cargala a mano en Compras.' } }];
}
return [{ json: { ok: true, url: r.url, texto: 'Hay una compra pre-cargada para revisar (' + r.renglones_reconocidos + ' renglones reconocidos, ' + (r.renglones_sin_reconocer || []).length + ' sin reconocer). Abrila, controlala contra la factura y confirmá: ' + r.url } }];

const r = $input.first().json;
const lineas = ['*Cafeto · mantenimiento del mes*', '',
  'Registros viejos que pasaron al histórico: ' + r.filas_al_historico,
  'Productos que cambiaron de proveedor habitual: ' + r.cantidad_reasignados];
for (const p of (r.productos_reasignados || []).slice(0, 15)) lineas.push('  · ' + p.producto + ': ' + p.antes + ' → ' + p.ahora);
const inactivos = r.proveedores_inactivos_6m || [];
if (inactivos.length) {
  lineas.push('', '*Proveedores sin movimiento hace más de 6 meses* (fijate si conviene darlos de baja)');
  for (const p of inactivos) lineas.push('  · ' + p.nombre + (p.ultima_compra ? ' (última compra ' + p.ultima_compra + ')' : ' (sin compras)'));
}
return [{ json: { texto: lineas.join('\n') } }];

// El token ya lo revisó el nodo «¿Trae el token de Cafeto?»: acá sólo
// se arma el texto. Antes esta validación vivía adentro de este Code y
// cortaba con «return []»: el flujo terminaba sin mandar nada y sin
// dejar rastro, así que un error del JS Task Runner (que en un equipo
// con poca memoria se cae solo) se veía igual que un token mal puesto.
const b = $('La caja pide autorización').first().json.body || {};
const renglones = (b.renglones || []).map(r => '• ' + r).join('\n');
const texto = '📲 *¿Autorizás?* ' + b.pedido + '.\n' +
  'Total del ticket: ' + b.total + '\n' + (renglones ? renglones + '\n' : '') +
  '\nPara aprobar: ' + b.enlace + '\n' +
  'O dictale este PIN a la caja: *' + b.pin + '*\n' +
  'Vale hasta las ' + b.vence + '.';
return [{ json: { texto } }];

const archivo = $input.first().binary.data;
const mensaje = $('Llega un WhatsApp con la factura').first().json.body.payload;
return [{ json: { nombre: archivo.fileName || 'factura', tipo: archivo.mimeType, archivo: archivo.data, origen: 'WHATSAPP', remitente: String(mensaje.from || '').replace('@c.us', '') } }];

const salida = [];
for (const item of $input.all()) {
  for (const [clave, archivo] of Object.entries(item.binary || {})) {
    if (!/pdf|image|text/.test(archivo.mimeType || '')) continue;
    salida.push({ json: { nombre: archivo.fileName || clave, tipo: archivo.mimeType, archivo: archivo.data, origen: 'CORREO', remitente: String(item.json.from || '').slice(0, 80) } });
  }
}
return salida;

const r = $input.first().json;
if (!r.en_bandeja) {
  return [{ json: { texto: 'No pude leer la factura que mandaste (' + (r.detail || 'sin detalle') + '). Cargala a mano en Compras.' } }];
}
return [{ json: { texto: (r.ya_estaba ? 'Esa factura ya estaba esperando. ' : 'Recibí la factura. ') + 'Tenés ' + r.pendientes + ' para revisar y confirmar en Compras: ' + r.url } }];

const p = $('Uno por producto').item.json;
const d = $input.item.json;
const url = d && d.status === 1 && d.product ? d.product.image_front_url : '';
if (!url) return null;
return { json: { id: p.id, url: url.replace(/^http:/, 'https:') } };

// Un solo mensaje, corto: qué receta cargar primero (la que más plata
// movió) y qué se está vendiendo sin costo o a pérdida. Lo demás espera.
const recetas = $('Elaborados sin receta').first().json || {};
const margenes = $input.first().json || {};
// Si una de las dos consultas contestó un error, lo que falta queda vacío
// y el mensaje sale con la mitad que sí se pudo leer.
const sinReceta = Array.isArray(recetas.productos) ? recetas.productos : [];
const conMargen = Array.isArray(margenes.productos) ? margenes.productos : [];
const dias = recetas.dias || 7;
const piso = margenes.piso === undefined ? 15 : margenes.piso;
const plata = (n) => '$ ' + Number(n).toLocaleString('es-AR', {minimumFractionDigits: 2});
const lineas = ['*Cafeto · la revisión del lunes*'];
if (recetas.total_pendientes) {
  lineas.push('', '*Recetas que faltan* (' + recetas.total_pendientes + ' en total)');
  for (const p of sinReceta) {
    const vendido = Number(p.facturado) > 0
      ? ' · vendió ' + plata(p.facturado) + ' en ' + dias + ' días'
      : ' · todavía sin ventas';
    lineas.push('  · ' + p.nombre + vendido);
  }
}
const perdida = conMargen.filter((p) => p.motivo !== 'MARGEN_BAJO');
const bajos = conMargen.filter((p) => p.motivo === 'MARGEN_BAJO');
if (perdida.length) {
  lineas.push('', '*Sin costo o a pérdida*');
  for (const p of perdida.slice(0, 5)) {
    lineas.push('  · ' + p.nombre + ' (' + (p.motivo === 'SIN_COSTO' ? 'costo en $ 0' : 'se vende a pérdida') + ')');
  }
}
if (bajos.length) {
  lineas.push('', '*Margen por debajo del ' + piso + ' %*');
  for (const p of bajos.slice(0, 5)) {
    lineas.push('  · ' + p.nombre + ': ' + p.utilidad_porcentaje + ' %');
  }
}
if (lineas.length === 1) return [];
// El enlace es el del primer producto que TRAIGA url. Antes se tomaba
// (recetas.productos[0] || margenes.productos[0] || {}).url y, con las dos
// listas vacías o un objeto sin url, el mensaje terminaba en «undefined».
const destino = sinReceta.concat(conMargen)
  .map((p) => p && p.url)
  .find((u) => typeof u === 'string' && u.length > 0);
if (destino) lineas.push('', 'Para resolverlas: ' + destino);
return [{ json: { texto: lineas.join('\n') } }];

// Cinco productos, tres minutos, antes de abrir. Son los que figuran en
// cero (o en negativo) y sin embargo se siguen vendiendo: o nunca se
// contaron, o se venden sin descargar. Si no hay ninguno, no se manda nada.
const r = $input.first().json || {};
// Si el sistema contestó un error (sin "productos"), no hay misión: se
// sale en silencio en lugar de romper el nodo con un TypeError.
const productos = Array.isArray(r.productos) ? r.productos : [];
if (!productos.length) return [];
// Las cantidades llegan como decimal de PostgreSQL ("98.000", "12.600"):
// escritas tal cual, en la Argentina se leen como 98 mil y 12 mil 600. Van
// en es-AR y sin los ceros que no dicen nada: 98, 22, 12,6.
const unidades = (n) => Number(n).toLocaleString('es-AR', { maximumFractionDigits: 3 });
const lineas = ['*Cafeto · conteo de 3 minutos*', '',
  'Estos figuran en 0 y se siguen vendiendo. Contalos y cargá el conteo:'];
for (const p of productos) {
  const vendidas = Number(p.unidades_vendidas);
  const rotacion = vendidas > 0
    ? ' (salieron ' + unidades(vendidas) + ' en ' + (r.dias || 30) + ' días)'
    : ' (quedó en 0 desde la migración)';
  lineas.push('  · ' + p.nombre + rotacion);
}
lineas.push('', 'Quedan ' + (r.total || productos.length) + ' así en total. De a cinco por día se termina.');
return [{ json: { texto: lineas.join('\n') } }];

// Un item por producto, para consultar Open Food Facts de a uno.
// Si el sistema contestó un error (sin "productos"), no hay nada que
// recorrer: se sale en silencio en lugar de romper el flujo.
return ($input.first().json.productos || []).map((p) => ({ json: p }));

// El rubro se adivina con palabras del local; Open Food Facts sólo suma
// cuando el producto tiene código de barras y está en su catálogo.
// NADA se cambia acá: esto arma una sugerencia que aprueba una persona.
//
// La coincidencia es por PALABRA COMPLETA (con su plural), no por
// «contiene»: con includes(), «original» caía en Bebidas con Alcohol por
// «gin», «pañal» en Panadería por «pan» y «salsa» en Almacén por «sal».
// Y las frases más largas se prueban primero, así «crema de enjuague» va
// a Perfumería y no a Lácteos por la palabra «crema».
const LARGO_MOTIVO = 200;   // stock.SugerenciaCatalogo.motivo es CharField(200)
const LARGO_CATEGORIA = 60;
const p = $('Uno por producto').item.json;
const d = $input.item.json || {};
// El ORDEN de este objeto desempata entre palabras igual de específicas
// (misma cantidad de palabras y el mismo largo), porque el sort de abajo es
// estable. Dos desempates que importan:
//
//  * Cafetería va antes que Fiambrería y que Panadería: lo que el local
//    prepara y vende hecho —"BAGEL MULTICEREAL JAMON Y QUESO"— es de
//    Cafetería, no un fiambre. Sin esto ganaba 'jamon' (también de cinco
//    letras) y el bagel se proponía como Fiambrería.
//  * Perfumería y Limpieza van antes que Lácteos: ante dos palabras igual
//    de específicas (jabón, crema, desodorante) manda el rubro no
//    comestible.
const PALABRAS = {
  'Bebidas con Alcohol': ['cerveza', 'vino', 'fernet', 'whisky', 'vodka', 'gin', 'ginebra', 'aperitivo', 'champagne', 'sidra'],
  'Bebidas sin Alcohol': ['gaseosa', 'agua', 'jugo', 'soda', 'energizante', 'isotonica', 'tonica'],
  'Cafetería': ['bagel', 'sandwich', 'sanguche', 'tostado', 'panini', 'pebete', 'cafe con leche', 'capuchino'],
  'Fiambrería': ['jamon', 'salame', 'mortadela', 'bondiola', 'panceta', 'salchichon'],
  'Panadería': ['pan', 'factura', 'medialuna', 'bizcocho', 'tostada', 'budin', 'criollo'],
  'Kiosco': ['alfajor', 'chicle', 'caramelo', 'chocolate', 'turron', 'oblea', 'golosina'],
  'Perfumería': ['shampoo', 'jabon de tocador', 'papel higienico', 'pañal', 'desodorante', 'crema de enjuague', 'toallita'],
  'Limpieza': ['lavandina', 'detergente', 'jabon en polvo', 'desodorante de piso', 'esponja', 'trapo', 'suavizante'],
  'Lácteos': ['leche', 'yogur', 'queso', 'manteca', 'crema', 'dulce de leche', 'ricota'],
  'Almacén': ['fideo', 'arroz', 'harina', 'azucar', 'aceite', 'yerba', 'cafe', 'sal', 'salsa', 'pure', 'arveja', 'lenteja', 'conserva', 'galletita'],
};
const sinTildes = (t) => String(t == null ? '' : t).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
// Los pares (rubro, palabra) de la frase más específica a la más general:
// primero las de más palabras y, con la misma cantidad, la más larga. El
// orden del objeto resuelve los empates (sort es estable).
const CANDIDATOS = [];
for (const [rubro, palabras] of Object.entries(PALABRAS)) {
  for (const palabra of palabras) CANDIDATOS.push({ rubro, palabra, limpia: sinTildes(palabra) });
}
CANDIDATOS.sort((a, b) => (b.limpia.split(' ').length - a.limpia.split(' ').length)
  || (b.limpia.length - a.limpia.length));
// Palabra entera, admitiendo el plural del castellano («fideos»,
// «alfajores»). El \b alcanza porque el texto ya viene sin tildes y en
// minúsculas, y ninguna palabra de la lista lleva caracteres de regex.
const dice = (texto, limpia) => new RegExp('\\b' + limpia + '(?:es|s)?\\b').test(texto);
const buscar = (texto) => (texto ? CANDIDATOS.find((c) => dice(texto, c.limpia)) : undefined);

let rubro = '';
let razon = '';
const porNombre = buscar(sinTildes(p.nombre + ' ' + (p.marca || '')));
if (porNombre) {
  rubro = porNombre.rubro;
  razon = 'El nombre dice "' + porNombre.palabra + '"';
}
if (!rubro && d.status === 1 && d.product) {
  const porCategoria = buscar(sinTildes(d.product.categories || ''));
  if (porCategoria) {
    rubro = porCategoria.rubro;
    const primera = String(d.product.categories || '').split(',')[0].trim().slice(0, LARGO_CATEGORIA);
    razon = 'Open Food Facts lo tiene en "' + primera + '"';
  }
}
if (!rubro) return null;
// El motivo se corta acá y no en PostgreSQL: el truncado del backend
// dejaría la frase partida al medio sin que nadie se entere.
let motivo = razon + '. Hoy está en "' + (p.rubro_actual || 'sin rubro') + '".';
if (motivo.length > LARGO_MOTIVO) motivo = motivo.slice(0, LARGO_MOTIVO - 1).trimEnd() + '…';
return { json: { cuerpo: { producto: p.id, tipo: 'RUBRO', motivo, propuesta: { rubro } } } };
